  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (301::BIGINT, 'La verdad es que le entendía en los ejemplos que daba en las clases pero a la hora de hacer los quizzes me sentía perdido y no sabía que hacer, sin embargo los califica suave solo metale en las investigaciones y proyectos'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-22T00:00:00+00:00'::TIMESTAMPTZ, '040d119ba6630c853d5864b79a74543abce653670ea6d878af0735880fadde5a'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Si ya sabe lo básico de Python no va a tener problema en pasar fácil (da buenos ejemplos y los podrá entender). Si no sabe NADA probablemente va a terminar el curso sabiendo NADA porque no enseña cómo escribir código, si no como funcionan los ejemplos que ya trae escritos (pero se pasa fácil :)'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '78413d817517759e08c4fc896280431c10c5266e2f2252e9b09f782576b3bb22'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'El curso es dificil no importa con quien lo lleve (es mucha materia y nadie le enseña C++). Enseña muy bien para la complejidad del curso, da muchos ejemplos para la práctica. Los proyectos y laboratorios son dificiles pero califica suave.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Muchos exámenes']::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, '8605d52a180ae1f7e71beee82dd64a597df48c77f57d8f88a07604fe79c56d34'::TEXT, ARRAY[1253]::BIGINT[]),
    (301::BIGINT, 'En especial para este curso no explica NADA, va a pasar a puro Chat y no va a aprender nada. Como me dijeron antes de matricular con él: Usted no va a aprender nada pero pasa super fácil. Y es así pone 100 casi a todo. Evítelo, ya que al final termina siendo un estrés.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'e9545c7730a94b4c3c76e4b325c0246cd7600a57aec0c892c8506a91951adc85'::TEXT, ARRAY[1253]::BIGINT[]),
    (301::BIGINT, 'Sinceramente es por mucho el peor profesor de programacion que he tenido en toda mi vida, no explica absolutamente nada de codigo, uno pasa con ese profe porque es un vago tanto para enseñar como para calificar y con cualquier cochinada hecha con blackbox se lo califica bueno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-10-08T00:00:00+00:00'::TIMESTAMPTZ, '2d9152988c04291ea632b8dc556d193e4ae7316d91c0692a6a6e4c8708daae53'::TEXT, ARRAY[1253]::BIGINT[]),
    (301::BIGINT, 'El profesor exige al momento de entrgar el codigo que uno le explique lo cual debería de ser al reves que el me explique si tiene fallas y el porque. pretende que uno ya sepa todo de manera excelente.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-10-03T00:00:00+00:00'::TIMESTAMPTZ, '2c44e1422af9132a00dd4cfca1e90a76b3532f3433f252c54a50da18ac598560'::TEXT, ARRAY[1253]::BIGINT[]),
    (301::BIGINT, 'Con él se pasa relativamente fácil. Es de prestarle atención y hacer todo con tiempo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-26T00:00:00+00:00'::TIMESTAMPTZ, '3ffaca7b7458faafd9fd44ad283cdc3db375dd3e55d5b5347450cd9edce9d334'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'El profe es amable, pero sus clases son un poco aburridas y a veces no se le entiende bien. Los laboratorios son fáciles igual que los proyectos y él califica superbién. Para pasar es una buena elección, difícilmente se queda, pero si no tiene interés en el tema es posible que le resulte pesado.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '3a373ff393178fa150e50110cb8a79d28caa381992df8b75e651a5dc682fd826'::TEXT, ARRAY[1253]::BIGINT[]),
    (301::BIGINT, 'Respetuoso con los estudiantes. Deja laboratorios sencillos de manera semanal, los proyectos son largos y algo complejos, sin embargo, hay mucho material que le puede ayudar en Internet. El curso, finalmente, se pasa de manera relativamente sencilla.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2024-08-11T00:00:00+00:00'::TIMESTAMPTZ, '92b9e190730e257b2f74006021669a8ebaac517fc62cbf7f3da9b55604d08c39'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Un profe excelente, de esos que lo marcan a uno. Sí, los proyectos son duros pero los laboratorios son fáciles y sabe un montón. Además es muy comprensivo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2024-07-22T00:00:00+00:00'::TIMESTAMPTZ, '5e7ab7c4409f1579303f1f661483901ede42157bc8c8e45cbbed501514dbc19b'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Explica con ejemplos, tal vez sea difícil de entender, pero, ofrece material de apoyo y recomiendo páginas para ir aprendiendo, realmente depende de uno aprender o no, es organizado y no se atrasa con ir calificando. En consulta explica muy bien realmente.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'd6f6398b6b19c9baf994cbfa8ef9dd505d1254decf2c6cb36fd01bc222435a7c'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Si quiere pasar fácil o con buenta calificación, con él se logra, haciendo las varas se pasa, él no hace exámenes, aunque sus clases son para dormirse, si quiere aprender, aquí no es, pero si quiere pasar fácil con 9+, dele, porque las varas se hacen con gpt o gemini.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'eb30d9d0962c73ebd742927de95e9ea2b50d32f715dbec2a68aed107014aed72'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Como dicen otros, sus clases son aburridas aunque explica bien, pero para terminar de aprender bien si va ocupar recurrir a otras fuentes o al GPT, mientras se cumpla con la asistencia y entregue la mayoría de trabajos se pasa fácil la materia.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a443b5e35781e6c9e5789e3118b16c93115620d56d9251143283db60a21deb48'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Es bueno explicando pero es muy aburrido. Si hay que ser autodidacta si se quiere aprender bien. Los tres proyectos (60%) no son difíciles, los califica la asistente. El otro 40% es de asistencia y laboratorios, que básicamente lo regala.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '423d0ef3478919506434544d1acda0803a14200e0f7c3b2b329bb73e7e516893'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Sacar 9 es re-fácil con él, aunque si verdaderamente quiere aprender, con él no es, la clases son demasiado aburridas,1 es presencial, otra virtual; deja 3 proyectos y 16 laboratorios (tareas) todo se puede hacer con IA y la asistencia vale puntos, pero en teoría es el único bueno que da el curso'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, '097580b5d5be3e56c8c170a3a5a883b7bd23fc6239c546a1cbc1d60ce2c4aaa9'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'La clase con este profesor es muy fácil pero no se aprende nada porque no explica muy bien.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-02-05T00:00:00+00:00'::TIMESTAMPTZ, '431584e5a11f092b7f33191a2f4bbfde5f0e9795df0bf90c415e8691a581fad3'::TEXT, ARRAY[1253]::BIGINT[]),
    (301::BIGINT, 'No sabe dar clases no explica'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Asistencia obligatoria']::TEXT[], '2023-09-25T00:00:00+00:00'::TIMESTAMPTZ, '25ec024ea832cc29850b69ef9d68babee4e5a33bf630a4b66aae3810746c47fa'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Su forma de explicar es malísima, no se le entiende nada. Los labs son fáciles. Con solo entregarlo le da el 100 pero los proyectos valen mucho. Califica asistencia así que eso salva un toque y los proyectos que son lo que más vale los calificó el asistente. Matricule bajo su propio riesgo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'e06f2d2a105e79cd20da5c20924bad1c090dfba7d28ce4ddb3518a80d917440a'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'No explica de buena manera, los labs con solo entregarlos te da un 100 y luego los proyectos son super dificiles. Si no sabes nada de programación se te va a hacer muy díficil.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'f5c85c57024b79f7f694e28ef493e2d0be7182960651a327641449e1f0ce3121'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'No lo recomiendo, si no tiene otro horario con otro profesor mejor no matricule, si no sabe programar o es su primera vez se queda, de nada sirve que tengas 100 en los laboratorios solo por entregarlos porque después valen más los proyectos, califica muy duro y si algo no le parece te queda'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, '51665e3c68fbefe05d75ad4fe5b1f4997a8ba8a9d1ca25c5e92692cf68db6fd8'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Es el peor profe que he tenido. Literal la mitad de las cosas las enseñaba con páginas de intenet y luego en los proyectos califica súper duro y si uno lo hace de una manera que a él no le parece le pone todo malo. Las preguntas que pone no se entienden nada y según el las "explica"'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'cda1e9705b4ee262a5247e75ed197f12ef17f6b78b75e386d034a1376aa32ef2'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'El profe es considerado con el cambio de elementos a analisis. Los labs que deja son sencilllos, pero los proyectos son BASTANTE mas rudos en comparacion a los labs. La participacion importa.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c0e72527e9d61034205f49cfcead5f3a8bd7d0517d0f85a780f423d30fc9f882'::TEXT, ARRAY[1253]::BIGINT[]),
    (301::BIGINT, 'Deja laboratorios semanales que con solo entregarlos ya se tiene 100. No da ma retroalimentación de los programas. Explica un poco ambiguo y los proyectos son DUROS. La participación es MUY importante, yo trataba de participar bastante y llevo 6. Pero por la forma de calificar se pasa de fijo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '4b857954813333805ad155a279671114bb9f28f99f6051a6a78817a4ea93cfe5'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'El peor profesor que he tenido, no lo recomiendo es una embarcada, no explica bien y si usted es una persona que no sabe nada de programación le va a ir muy mal.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa']::TEXT[], '2022-05-26T00:00:00+00:00'::TIMESTAMPTZ, '24eec251856b0686d3b13085b5014a60c4f29f60b0fc7ad70ead98c64a410142'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'El curso por si solo es complicado más para una persona que no sabe nada de programar, sin embargo el profesor es bueno explicando y responde las veces que sea necesario la misma pregunta. Responde rápido si uno le hace preguntas por aparte.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'ab7d4f9dbda09758e1b51708719ac885f5d8f19ac93276b52c9ca131939ca105'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Las clases son presentaciones en inglés que él traduce a español, materia interesante pero clases meh. La mayoría de la nota es hacer un paper sobre algo relacionado con SO. El resto progras no tan difíciles (lenguaje libre)'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Clases largas']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b413bb9e554e44227162779adb1e04c70a5f2dfeeeabe7363734336b2743d1a3'::TEXT, ARRAY[337]::BIGINT[]),
    (301::BIGINT, 'Laboratorios semanales fáciles pero proyectos algo rudos, especialmente el primero. No es malo pero pueden haber mejores opciones'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '4dc45ca4ce07fab9c13961dfd7e6f081ebb611bfe1a4270f7c086175aefa3a51'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Fue mi segunda vez llevando este curso y tengo que decir que es de los mejores profes. Si tiene conocimientos de python este curso es prácticamente regalado, si no tiene o es su primera vez le aconsejo que vea videos en youtube porque él abarca muchos temas en poco tiempo, entonces se puede enredar'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'f00ea4888c0b74d17b9ac6c798f304961c5069ebba4193b5cc75c2a5742a422f'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'el profe como tal es bueno pero deja proyecto demasiado rudos. No lo recomiendo'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'ed464d8cd29fb618f775c9c693ec2824ac4bdb7bab1dfc30b9d1182de21423cb'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'A veces la clase se torna un poco aburrida pero en general el profe es bueno, ayuda y aclara las dudas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-10-23T00:00:00+00:00'::TIMESTAMPTZ, 'f06b11fa3656e0e0f8d14f03bbe335bafa66fb2cbdee46fb460d88e50d558175'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Es un buen profe, algunos temas los explica súper bien. Ayuda con las evaluaciones siempre y cuando uno ponga interés en la clase. No lo recomiendo solo porque deben haber profes mejores, pero no es tan malo como dicen.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '510e541cb91269308e24fe2301fe1b3634fbb344ee5700689e8442697bc055d2'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Es PÉSIMO. No revisa los labs, en todos tenés 100 si los entregás, pero no te vas a dar cuenta de cómo le gusta que programés. En el examen, tiene cero criterio de calificación, pone notas al azar. Lo más complicado que te enseña es a hacer un cuadrado que se mueva y te explota en el proyecto.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, '24abe5d3bbb93a8c9f16b12b5638b17423df53b1ec73dcf2410c9cf4ddf404a9'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'El conoce la materia, no lo recomendaria para alguien que lleva el curso por primera vez, ya que el asume que el estudiante sabe mucho de Paithon, y no aclara dudas muy bien.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'cfcf09eb991131f82528ade37c4c9caf3f57700955112e6d6429331a2a2cf393'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'Él conoce, pero ¡NO! sabe enseñar, asume que uno conoce todo de python, NO ayuda si uno tiene una consulta durante la clase. Llega a ser un toque odioso, y lo hace sentir a usted como tonto. Lo único bueno es que al PRINCIPIO del curso, los trabajos con solo presentarlos se saca 100. NO RECOMENDADO.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-11-05T00:00:00+00:00'::TIMESTAMPTZ, '82d0b9e6e22c15599f9eec856f8a1ef02c49cb7e9b400260d58860ef56f6e933'::TEXT, ARRAY[1249]::BIGINT[]),
    (301::BIGINT, 'sabe muchisimo y es super dedicado. De los mejores profesores que he tenido'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-02T00:00:00+00:00'::TIMESTAMPTZ, 'f8e72fc209471705bbca6477a99dc6dbb38933258d2d96f2627b1fd08436e4fd'::TEXT, ARRAY[329]::BIGINT[]),
    (301::BIGINT, 'Sabe de lo que habla, pero no tiene idea de cómo explicarlo. Sus clasea son tediosas, aburridas e incomprensibles. Los proyectos son poco claros e injustificadamente exigentes. Un pésimo profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'a05fc70e6b22e1f94d1c3f16df69fc7165abcce633a5fd8ab03c1eaff1279805'::TEXT, ARRAY[2534]::BIGINT[]),
    (301::BIGINT, 'Sabe mucho y le gusta compartir lo que sabe. Te ayuda mucho si le llegás con preguntas específicas y claras. Lo podés contactar en cualquier momento y te va a contestar. Tiene una disponibilidad muy muy alta. Excelente para que apoye a guiar un tesis o proyecto de graduación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2015-08-17T00:00:00+00:00'::TIMESTAMPTZ, '04ca69d8b990818eb77082a48ff672750e226fd2f12daac4ece2fd90fc07f184'::TEXT, ARRAY[45]::BIGINT[]),
    (301::BIGINT, 'Es un profesor que conoce completamente del tema que debe hablar pero no sabe el como explicarse, por lo que hace que la clase sea confusa, muy confusa. Además, sus clases son eternas por lo que las 2 horas en clases se hacen larguisimas, y legalmente todo el mundo se duerme!'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '33d9da0f9950ce998f57d5bdd127c193729ce45b7906f3b9b0dae7abb1197c22'::TEXT, ARRAY[2534]::BIGINT[]),
    (301::BIGINT, 'De los peores profesores que he tenido.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'a45a4540d4e59349d1d4d444a84357d0a31ee5ff3c0437b657ab3902ab28e049'::TEXT, ARRAY[2534, 2543]::BIGINT[]),
    (301::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '13ece00e6b2839a09f50dab7ca0be194dd92cca9884e631e49af363a25c46a49'::TEXT, ARRAY[2534]::BIGINT[]),
    (301::BIGINT, 'Sabe mucho, pero queda debiendo como profesor, tiene un problema nunca se le queda bien y el tiene la verdad absoluta. Sus especificaciones en los trabajos son muy generales y siempre quiere más de lo que pide.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '604062e19e7ae4ce221c985d557c14f75ddf23f3ac8758db540eca51450b6d44'::TEXT, ARRAY[2573]::BIGINT[]),
    (301::BIGINT, 'El profe sabe bastante en el área de TI, sin embargo sus clases son muy teóricas y aburridas. Sin embargo, las clases de Formulación de proyectos son un poco menos tediosas que las que da en Infraestructura I.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '9edb40e756de3f8dfccdb2accfd3116cfcda5aa18f84997e4c423a96834e6251'::TEXT, ARRAY[91, 2644, 2211, 3646, 355, 4161, 3137]::BIGINT[]),
    (301::BIGINT, 'En las clases con él, el tiempo se detiene, es demasiado aburrido, sabe muchísimo, pero no sabe explicar'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'daacfc2d88d5dfa6b8dabfc85138b236d10d892bbf141ed50cfcb53d8ba60dd5'::TEXT, ARRAY[2534]::BIGINT[]),
    (301::BIGINT, 'Es un profesor que no especifica bien las cosas. Es muy subjetivo a la hora de calificar. No lo recomiendo como profe. Los cursos son muy teóricos. No sabe ni como explicar'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '2eecd10947d8e5fa92b2a233b8b4589af55717a07768fdaa0a119a5eef413be5'::TEXT, ARRAY[2543]::BIGINT[]),
    (301::BIGINT, 'Un bostezo de clases, y muchas veces no tiene un control sobre la materia, habla mucho pero divaga y uno tiende a perderse.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'b2cd36ba000aace8c582fc45d07ddeed25d9c7e99c06556ef925b58b37a98c7b'::TEXT, ARRAY[337]::BIGINT[]),
    (301::BIGINT, 'Es muy inteligente, sabe mucho, pero cuando deja trabajos no especifica qué es lo que quiere en realidad y cuando los revisa califica sumamente duro'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '4c0cb6d9cf3df947df3e7fa5fcdd93f872242ee68a98f95219a1bbb0b71f771f'::TEXT, ARRAY[2543]::BIGINT[]),
    (301::BIGINT, 'El mae sabe demasiado, es un crack pero la clase es la más aburrida que existe, lo conocen por aburridin en la escuela es por algo. Los quices son reventados, los exámenes son imposibles. La materia de muy bajo nivel. Proyectos demasiado volados.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'cf47bc84b84de86435fa34c4eb5a7cfe436dbaf061ae51e023af00809d6cb0a5'::TEXT, ARRAY[337, 2534]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
